"""Собирает flavor-data.json: дерево колеса + авторские тексты панели."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TREE = json.loads((ROOT / "assets" / "flavor-tree-wheel.json").read_text(encoding="utf-8"))

# slug -> (orbitElement, sense, how, tip)
# sense — уникальная вкусовая зацепка; how и tip — готовые абзацы.
T = {}

def add(slug, orbit, sense, how, tip):
    T[slug] = (orbit, sense, how, tip)

